/**
 * Google Cloud Firestore Node - Version 1.1
 * Discriminator: resource=document, operation=query
 */


interface Credentials {
  googleFirebaseCloudFirestoreOAuth2Api: CredentialReference;
  googleApi: CredentialReference;
}

/** Runs a query against your documents */
export type GoogleFirebaseCloudFirestoreV11DocumentQueryParams = {
  resource: 'document';
  operation: 'query';
  authentication?: 'googleFirebaseCloudFirestoreOAuth2Api' | 'serviceAccount' | Expression<string>;
/**
 * As displayed in firebase console URL. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
 * @loadOptionsMethod getProjects
 */
    projectId: string | Expression<string>;
/**
 * Usually the provided default value will work
 * @default (default)
 */
    database?: string | Expression<string>;
/**
 * JSON query to execute. Use $1, $2, and so on as complete values to reference Query Parameters below.
 * @hint Use query parameters for dynamic values instead of embedding expressions in the query
 */
    query: string | Expression<string>;
/**
 * Array of values to use for $1, $2, and so on, in order. Values can be strings, numbers, booleans, null, or arrays of these values.
 * @hint Build the array inside the expression, for example {{ [$json.name, 30] }} sets $1 to the name and $2 to 30
 * @default ={{ [] }}
 */
    queryParameters?: IDataObject | string | Expression<string>;
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @default true
 */
    simple?: boolean | Expression<boolean>;
};

export type GoogleFirebaseCloudFirestoreV11DocumentQueryOutput = {
  _createTime?: string;
  _id?: string;
  _name?: string;
  _updateTime?: string;
};

export type GoogleFirebaseCloudFirestoreV11DocumentQueryNode = {
  type: 'n8n-nodes-base.googleFirebaseCloudFirestore';
  version: 1.1;
  config: NodeConfig<GoogleFirebaseCloudFirestoreV11DocumentQueryParams> & { credentials?: Credentials };
  output?: Items<GoogleFirebaseCloudFirestoreV11DocumentQueryOutput>;
};